package com.dunerealms.atelier;
import java.sql.*;
import java.util.*;
import com.google.gson.*;
/** Paid receipts are immutable. Delivery consumption shares the inventory checkpoint transaction. */
public final class DeliveryStore {
 public record Design(String id,String name,String color,List<String> lore,String quality){}
 public record Pending(String id,String name,String quality){}
 static final List<String> TIERS=List.of("common","uncommon","rare","very_rare","legendary");
 static String plain(JsonElement value,int limit){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Plain text required");String raw=value.getAsString();String s=raw.strip();if(s.isEmpty()||s.codePointCount(0,s.length())>limit||raw.chars().anyMatch(c->c<32||c==127||c=='<'||c=='>'||c==167))throw new IllegalArgumentException("Invalid design text");return s;}
 static Design parse(String json){if(json==null||json.length()>16384)throw new IllegalArgumentException("Invalid design");JsonObject o=JsonParser.parseString(json).getAsJsonObject();String id=plain(o.get("blueprintId"),36);UUID.fromString(id);String quality=plain(o.get("quality"),16);if(!TIERS.contains(quality))throw new IllegalArgumentException("Invalid quality");String color=plain(o.get("color"),7);if(!color.matches("#[0-9a-fA-F]{6}"))throw new IllegalArgumentException("Invalid color");JsonArray lines=o.getAsJsonArray("lore");if(lines==null||lines.size()>6)throw new IllegalArgumentException("Invalid lore");List<String> lore=new ArrayList<>();for(JsonElement line:lines)lore.add(plain(line,120));return new Design(id,plain(o.get("name"),64),color,List.copyOf(lore),quality);}
 public List<Pending> pending(Connection c,UUID player,boolean queuedOnly)throws SQLException{List<Pending> rows=new ArrayList<>();try(PreparedStatement q=c.prepareStatement("SELECT id,snapshot_json FROM dune_kit_sales WHERE buyer_uuid=? AND delivered_at IS NULL"+(queuedOnly?" AND redeem_requested_at IS NOT NULL":"")+" ORDER BY completed_at,id LIMIT 25")){q.setString(1,player.toString());try(ResultSet r=q.executeQuery()){while(r.next()){Design d=parse(r.getString(2));rows.add(new Pending(r.getString(1),d.name(),d.quality()));}}}return rows;}
 public Design lock(Connection c,UUID player,UUID order)throws SQLException{if(c.getAutoCommit())throw new SQLException("Fenced inventory transaction required");try(PreparedStatement q=c.prepareStatement("SELECT buyer_uuid,snapshot_json,delivered_at FROM dune_kit_sales WHERE id=? FOR UPDATE")){q.setString(1,order.toString());try(ResultSet r=q.executeQuery()){if(!r.next()||!player.toString().equals(r.getString(1))||r.getObject(3)!=null)throw new SQLException("Paid item receipt unavailable");return parse(r.getString(2));}}}
 public void delivered(Connection c,UUID player,UUID order,long now)throws SQLException{if(c.getAutoCommit())throw new SQLException("Fenced inventory transaction required");try(PreparedStatement q=c.prepareStatement("UPDATE dune_kit_sales SET delivered_at=?,redeem_requested_at=COALESCE(redeem_requested_at,?) WHERE id=? AND buyer_uuid=? AND delivered_at IS NULL")){q.setLong(1,now);q.setLong(2,now);q.setString(3,order.toString());q.setString(4,player.toString());if(q.executeUpdate()!=1)throw new SQLException("Item receipt already consumed");}}
}
